import{_ as e,o as r,c as t,x as i}from"./chunks/framework.DzQQ_lrg.js";const b=JSON.parse('{"title":"大西洋慈善基金会的档案：有人接收，能否说已经有序退场","description":"接收馆的说明能确认“记录有人接收”，还不足以判断整家机构的退场是否完成。","frontmatter":{"title":"大西洋慈善基金会的档案：有人接收，能否说已经有序退场","description":"接收馆的说明能确认“记录有人接收”，还不足以判断整家机构的退场是否完成。","kind":"真实案例","source_type":"接收馆的馆藏说明与查检指南","concepts":["orderly-exit","carrier-and-responsibility"]},"headers":[],"relativePath":"cases/atlantic-archives-exit.md","filePath":"cases/atlantic-archives-exit.md"}'),l={name:"cases/atlantic-archives-exit.md"};function o(n,a,s,h,c,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="大西洋慈善基金会的档案-有人接收-能否说已经有序退场" tabindex="-1">大西洋慈善基金会的档案：有人接收，能否说已经有序退场 <a class="header-anchor" href="#大西洋慈善基金会的档案-有人接收-能否说已经有序退场" aria-label="Permalink to &quot;大西洋慈善基金会的档案：有人接收，能否说已经有序退场&quot;">​</a></h1><p>一家机构在结束之前为自己的档案找好了去处，能不能说它的退场有了交代？大西洋慈善基金会（The Atlantic Philanthropies，下文称Atlantic）是一家限期运作的基金会。康奈尔大学图书馆的馆藏说明写道，2015年9月康奈尔获得一笔资助，用来收藏、整理和推广Atlantic的档案；康奈尔的校方新闻当时报道，这笔资助出自基金会自己。馆藏说明没有标注日期，文中仍说基金会将在2020年关闭；基金会网站现在的说法是，它已在2020年完成工作。</p><h2 id="馆方记了什么" tabindex="-1">馆方记了什么 <a class="header-anchor" href="#馆方记了什么" aria-label="Permalink to &quot;馆方记了什么&quot;">​</a></h2><p>馆藏说明分开写了两组材料。一组是Atlantic自己的档案：公司记录（包括限定机构寿命的决定和结束工作所采取的步骤）、从申请到最终报告的资助档案、成效故事、评估与经验总结。部分材料限制查阅，查检指南（finding aid）逐件标出受限的案卷。这批档案哪一年移交康奈尔，馆藏说明和查检指南的概览都没有写。</p><p>另一组列在“Related Collections”（相关馆藏）之下，是哥伦比亚大学做的口述史：访谈分两期，第二期由Atlantic出资；2018年，哥伦比亚把录音和转录稿的数字副本交给康奈尔，原件留在哥伦比亚。查检指南按受访者写明哪些访谈受限、限到何时、调阅须经谁同意。</p><h2 id="从这里读懂一个区别" tabindex="-1">从这里读懂一个区别 <a class="header-anchor" href="#从这里读懂一个区别" aria-label="Permalink to &quot;从这里读懂一个区别&quot;">​</a></h2><p>《Xikari-条件结构与转化论》把有序退场记作X0，完成条件分七个面：锚点与对象、核心功能、人员与关系、资源、记忆与证据、债务与责任、弱连接。档案有人接收，对应的只是“记忆与证据”一面。原文对这一面的要求是“成功、失败、修复、岗位记忆均保存；访问、隐私、纠错和反报复明确”，失败信号是“只保留胜利史，删除或暴露弱势材料”。<a href="/xi-kari-skill/handbook/theory/part-08.html#section-8-5-2">阅读原文：§8.5.2</a></p><p>对照来看，哪些材料限制查阅，有明文可查。失败与修复的记录保存到什么程度，纠错和反报复怎样安排，从这些说明文字看不出来。</p><h2 id="还不能推出什么" tabindex="-1">还不能推出什么 <a class="header-anchor" href="#还不能推出什么" aria-label="Permalink to &quot;还不能推出什么&quot;">​</a></h2><p>其余六个面，这些材料都不足以核对。原文的规则是：</p><blockquote><p>只要受影响群体、遗留义务、接收能力、申诉或记忆安全仍为未知，就不能写“良性完成”。</p></blockquote><p>所以能记下的是一项局部事实：记录有了接收方。整体是否完成，记为未知；未知不等于失败，这些材料同样不支持“退场失败”。</p><p>这些说明出自接收方和基金会自己，接收方又是基金会的受资助者，不能充当“锚点与对象”一面要求的“完成、终止或失效的独立验证”。图书馆接下的是记录的保存与整理；基金会若还有未了的义务，由谁持续负责，属于“债务与责任”一面，要另找依据。</p><h2 id="读完自测" tabindex="-1">读完自测 <a class="header-anchor" href="#读完自测" aria-label="Permalink to &quot;读完自测&quot;">​</a></h2><p><strong>馆藏说明在2015年和2018年各记了一件事，哪一年是Atlantic自己的档案移交康奈尔的日期？</strong> 都不是。2015年是拨给档案工作的资助，2018年是口述史副本的交接；不能拿另一组馆藏的年份来补没有写出的日期。</p><p><strong>部分档案限制查阅，能不能记作“记忆与证据”一面的失败信号？</strong> 不能。原文列出的失败信号里没有限制查阅，倒有“暴露弱势材料”；这一面要求的是把访问条件写明。</p><h2 id="对照概念与原文" tabindex="-1">对照概念与原文 <a class="header-anchor" href="#对照概念与原文" aria-label="Permalink to &quot;对照概念与原文&quot;">​</a></h2><ul><li><a href="/xi-kari-skill/handbook/concepts/responsibility.html">实际承接与责任依据</a></li><li><a href="/xi-kari-skill/handbook/theory/part-08.html#section-8-5">§8.5 X0 有序退场与良性消亡</a></li><li><a href="/xi-kari-skill/handbook/theory/part-08.html#section-8-5-2">§8.5.2 X0 完成条件</a></li></ul><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><ul><li>Cornell University Library, Division of Rare and Manuscript Collections：<a href="https://rare.library.cornell.edu/atlantic-philanthropies-archives/" target="_blank" rel="noreferrer">Atlantic Philanthropies Archives</a>（馆藏说明，未标日期）；查检指南<a href="https://archives.library.cornell.edu/repositories/2/resources/8383" target="_blank" rel="noreferrer">The Atlantic Philanthropies Archives, #8540</a>、<a href="https://archives.library.cornell.edu/repositories/2/resources/8812" target="_blank" rel="noreferrer">Columbia University Atlantic Philanthropies oral history project, #8737</a>。</li><li>Cornell Chronicle：<a href="https://news.cornell.edu/stories/2015/10/archives-atlantic-philanthropies-given-cornell-library" target="_blank" rel="noreferrer">Archives of Atlantic Philanthropies given to Cornell Library</a>，2015年10月23日。</li><li>The Atlantic Philanthropies：<a href="https://www.atlanticphilanthropies.org/" target="_blank" rel="noreferrer">网站首页</a>。</li></ul><p>以上网页均于2026年11月12日读取。</p>',21)])])}const u=e(l,[["render",o]]);export{b as __pageData,u as default};
